    """Bridge gaps between collinear occurrences of the non-background color."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    marks = {v for v in counts if v != bg}
    out = [row[:] for row in grid]
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] in marks]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] in marks]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
'''
